// Verifies a Convex -> n8n webhook. Runs in an n8n Code node ("Run Once for All Items").
// Canonical scheme "v1" (must match convex/lib/signing.ts):
//   signature = "v1=" + hex(HMAC_SHA256(secret, "v1:" + timestamp + ":" + deliveryId + ":" + rawBody))
// The Webhook node has "Raw Body" enabled, so we hash the exact bytes Convex sent
// instead of re-serialising parsed JSON (which would not reproduce the same bytes).
const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;
const SIGNATURE_PATTERN = /^v1=[0-9a-f]{64}$/;
const RECIPIENT_ROLE_BY_EVENT = {
  'request.created': 'lender',
  'request.approved': 'borrower',
  'request.declined': 'borrower',
  'request.cancelled': 'lender',
};
const STATUS_BY_EVENT = {
  'request.created': 'pending',
  'request.approved': 'approved',
  'request.declined': 'declined',
  'request.cancelled': 'cancelled',
};
const ISO_DAY = /^\d{4}-\d{2}-\d{2}$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL = /^[^\s@<>]{1,64}@[^\s@<>]{1,255}$/;
const SAFE_ID = /^[\w.:#-]{3,200}$/;

const reject = (httpStatus, error) => [{ json: { ok: false, httpStatus, error } }];
const isText = (value, max) => typeof value === 'string' && value.length > 0 && value.length <= max;

const secret = $env.CONVEX_N8N_WEBHOOK_SECRET;
if (!secret || secret.length < 32) return reject(500, 'server_misconfigured');

const headers = $input.first().json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const deliveryId = String(headers['x-lendloop-delivery-id'] || '');
const signature = String(headers['x-lendloop-signature'] || '');

if (!SIGNATURE_PATTERN.test(signature) || !/^\d{10}$/.test(timestamp) || !SAFE_ID.test(deliveryId)) {
  return reject(400, 'malformed_signature_headers');
}

let rawBody;
try {
  rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (error) {
  return reject(400, 'missing_body');
}

// Freshness first (cheap), then the HMAC.
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(timestamp)) > TOLERANCE_SECONDS) return reject(401, 'stale_request');

const expected = crypto
  .createHmac('sha256', secret)
  .update('v1:' + timestamp + ':' + deliveryId + ':')
  .update(rawBody)
  .digest('hex');
const expectedBuffer = Buffer.from('v1=' + expected, 'utf8');
const presentedBuffer = Buffer.from(signature, 'utf8');
if (expectedBuffer.length !== presentedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, presentedBuffer)) {
  return reject(401, 'invalid_signature');
}

// Replay protection is layered: the timestamp window above bounds how long a captured
// request stays usable, and Convex accepts each signed deliveryId exactly once at
// /n8n/events/claim (authoritative, transactional). Workflow static data is deliberately
// NOT used: it did not persist reliably across webhook executions in testing.

let payload;
try {
  payload = JSON.parse(rawBody.toString('utf8'));
} catch (error) {
  return reject(400, 'invalid_json');
}

// Schema validation (n8n has no zod; keep this strict and explicit).
const valid =
  payload &&
  payload.schemaVersion === 1 &&
  SAFE_ID.test(String(payload.eventId)) &&
  payload.deliveryId === deliveryId &&
  UUID.test(String(payload.correlationId)) &&
  Object.prototype.hasOwnProperty.call(RECIPIENT_ROLE_BY_EVENT, payload.eventType) &&
  Number.isInteger(payload.attempt) &&
  payload.recipient &&
  isText(payload.recipient.name, 100) &&
  EMAIL.test(String(payload.recipient.email)) &&
  isText(payload.counterpartName, 100) &&
  payload.tool &&
  isText(payload.tool.name, 80) &&
  payload.request &&
  ISO_DAY.test(String(payload.request.startDate)) &&
  ISO_DAY.test(String(payload.request.endDate)) &&
  (payload.request.message === null || isText(payload.request.message, 500)) &&
  typeof payload.actionUrl === 'string' &&
  /^https?:\/\//.test(payload.actionUrl);
if (!valid) return reject(400, 'invalid_payload');

// n8n decides the recipient from the event type and cross-checks what Convex sent.
if (payload.recipient.role !== RECIPIENT_ROLE_BY_EVENT[payload.eventType]) return reject(400, 'recipient_mismatch');
if (payload.request.status !== STATUS_BY_EVENT[payload.eventType]) return reject(400, 'status_mismatch');

return [{ json: { ok: true, httpStatus: 202, payload } }];

const route = "/n8n/events/claim";
const payload = { eventId: $('Verify signature').first().json.payload.eventId, deliveryId: $('Verify signature').first().json.payload.deliveryId };
// Prepended by scripts/build-n8n-workflows.mjs: `const route = "/n8n/..."; const payload = { ... };`
// Produces the exact bytes to send and, when N8N_CONVEX_SIGNING_SECRET is set, an HMAC over them.
// Scheme (v1, same as Convex -> n8n): "v1=" + hex(HMAC_SHA256(secret, "v1:" + timestamp + ":" + route + ":" + body)).
const crypto = require('crypto');

const body = JSON.stringify(payload);
const headers = {};
const secret = $env.N8N_CONVEX_SIGNING_SECRET;
if (secret) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`v1:${timestamp}:${route}:${body}`).digest('hex');
  headers['X-LendLoop-Timestamp'] = timestamp;
  headers['X-LendLoop-Signature'] = `v1=${digest}`;
}

return { json: { ...$json, convexRequest: { body, headers } } };

// Builds the notification text for a request event. Pure formatting: no network, no secrets.
const payload = $('Verify signature').first().json.payload;

const escapeHtml = (value) =>
  String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const oneLine = (value) => String(value).replace(/[\r\n]+/g, ' ').trim();

const tool = oneLine(payload.tool.name);
const who = oneLine(payload.counterpartName);
const dates = payload.request.startDate + ' to ' + payload.request.endDate;

const templates = {
  'request.created': {
    subject: 'New borrow request for ' + tool,
    headline: who + ' would like to borrow ' + tool + ' (' + dates + ').',
    next: 'Review the request and approve or decline it.',
  },
  'request.approved': {
    subject: 'Your request for ' + tool + ' was approved',
    headline: 'Good news! ' + who + ' approved your request to borrow ' + tool + ' (' + dates + ').',
    next: 'Arrange the handover with the lender and return the tool by ' + payload.request.endDate + '.',
  },
  'request.declined': {
    subject: 'Your request for ' + tool + ' was declined',
    headline: who + ' declined your request to borrow ' + tool + ' (' + dates + ').',
    next: 'Browse other available tools or try different dates.',
  },
  'request.cancelled': {
    subject: who + ' cancelled their request for ' + tool,
    headline: who + ' cancelled their request to borrow ' + tool + ' (' + dates + ').',
    next: 'No action is needed.',
  },
};
const template = templates[payload.eventType];

const noteText = payload.request.message ? '\nTheir note: "' + payload.request.message + '"\n' : '';
const noteHtml = payload.request.message ? '<blockquote>' + escapeHtml(payload.request.message) + '</blockquote>' : '';

return [
  {
    json: {
      to: payload.recipient.email,
      subject: template.subject,
      text:
        'Hi ' + oneLine(payload.recipient.name) + ',\n\n' + template.headline + '\n' + noteText + '\n' +
        template.next + '\n' + payload.actionUrl + '\n\n- LendLoop: Borrow what you need. Lend what you don\'t.',
      html:
        '<p>Hi ' + escapeHtml(oneLine(payload.recipient.name)) + ',</p><p>' + escapeHtml(template.headline) + '</p>' +
        noteHtml + '<p>' + escapeHtml(template.next) + '</p><p><a href="' + escapeHtml(payload.actionUrl) + '">Open LendLoop</a></p>' +
        '<p style="color:#6b7280">LendLoop: Borrow what you need. Lend what you don\'t.</p>',
    },
  },
];

const route = "/n8n/events/result";
const payload = { eventId: $('Verify signature').first().json.payload.eventId, outcome: 'sent' };
// Prepended by scripts/build-n8n-workflows.mjs: `const route = "/n8n/..."; const payload = { ... };`
// Produces the exact bytes to send and, when N8N_CONVEX_SIGNING_SECRET is set, an HMAC over them.
// Scheme (v1, same as Convex -> n8n): "v1=" + hex(HMAC_SHA256(secret, "v1:" + timestamp + ":" + route + ":" + body)).
const crypto = require('crypto');

const body = JSON.stringify(payload);
const headers = {};
const secret = $env.N8N_CONVEX_SIGNING_SECRET;
if (secret) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`v1:${timestamp}:${route}:${body}`).digest('hex');
  headers['X-LendLoop-Timestamp'] = timestamp;
  headers['X-LendLoop-Signature'] = `v1=${digest}`;
}

return { json: { ...$json, convexRequest: { body, headers } } };

// Maps a Send Email error to a coarse, non-sensitive code and a retry hint for Convex.
// The raw error text is never forwarded: it can contain addresses or server banners.
// With "continue (using error output)" the error arrives as a string or an object, depending on the node.
const rawError = $json.error;
const text = String(
  typeof rawError === 'string' ? rawError : (rawError && (rawError.message || rawError.description)) || '',
).toLowerCase();

const rules = [
  { match: /timeout|timed out|etimedout/, code: 'SMTP_TIMEOUT', retryable: true },
  { match: /econnrefused|enotfound|econnreset|getaddrinfo|socket/, code: 'SMTP_UNREACHABLE', retryable: true },
  { match: /\b4\d\d\b|rate|too many|throttl/, code: 'SMTP_TEMPORARY', retryable: true },
  { match: /auth|535|credential/, code: 'SMTP_AUTH', retryable: false },
  { match: /recipient|mailbox|address|550|553/, code: 'SMTP_REJECTED_RECIPIENT', retryable: false },
];
const found = rules.find((rule) => rule.match.test(text));
return [{ json: { errorCode: found ? found.code : 'SEND_FAILED', retryable: found ? found.retryable : true } }];

const route = "/n8n/events/result";
const payload = { eventId: $('Verify signature').first().json.payload.eventId, outcome: 'failed', errorCode: $json.errorCode, retryable: $json.retryable };
// Prepended by scripts/build-n8n-workflows.mjs: `const route = "/n8n/..."; const payload = { ... };`
// Produces the exact bytes to send and, when N8N_CONVEX_SIGNING_SECRET is set, an HMAC over them.
// Scheme (v1, same as Convex -> n8n): "v1=" + hex(HMAC_SHA256(secret, "v1:" + timestamp + ":" + route + ":" + body)).
const crypto = require('crypto');

const body = JSON.stringify(payload);
const headers = {};
const secret = $env.N8N_CONVEX_SIGNING_SECRET;
if (secret) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`v1:${timestamp}:${route}:${body}`).digest('hex');
  headers['X-LendLoop-Timestamp'] = timestamp;
  headers['X-LendLoop-Signature'] = `v1=${digest}`;
}

return { json: { ...$json, convexRequest: { body, headers } } };
